CREATE TABLE meta(key TEXT PRIMARY KEY, value TEXT) STRICT; CREATE TABLE files( id INTEGER PRIMARY KEY, host TEXT NOT NULL, agent TEXT NOT NULL, relpath TEXT NOT NULL, kind TEXT NOT NULL DEFAULT 'transcript', project TEXT, session TEXT, subagent INTEGER NOT NULL DEFAULT 0, title TEXT, cost_usd REAL, cwd TEXT, src_size INTEGER, src_mtime REAL, archived_size INTEGER NOT NULL DEFAULT 0, zst_size INTEGER NOT NULL DEFAULT 0, indexed_bytes INTEGER NOT NULL DEFAULT 0, index_level TEXT NOT NULL DEFAULT 'full', first_ts TEXT, last_ts TEXT, UNIQUE(host, agent, relpath) ) STRICT; CREATE INDEX files_session ON files(agent, session); CREATE TABLE docs( id INTEGER PRIMARY KEY, file_id INTEGER NOT NULL, ts TEXT, role TEXT, kind TEXT, tool TEXT ) STRICT; CREATE INDEX docs_file ON docs(file_id); CREATE TABLE history( id INTEGER PRIMARY KEY, host TEXT NOT NULL, agent TEXT NOT NULL, ts TEXT, project TEXT, text TEXT NOT NULL, UNIQUE(host, agent, ts, project, text) ) STRICT; CREATE VIRTUAL TABLE fts USING fts5(text, tokenize='trigram'); CREATE VIRTUAL TABLE fts_words USING fts5(text, tokenize='unicode61'); CREATE VIRTUAL TABLE hist_fts USING fts5(text, tokenize='trigram');
PRAGMA busy_timeout = 30000;
PRAGMA journal_mode = WAL;
PRAGMA synchronous = NORMAL;
PRAGMA user_version = ${INDEX_VERSION};

